// M06-T01: every seeded archetype row resolves in the typed registry,
// directly or through the alias table, ids are unique, and every original
// a def names is pinned by sha256. Expected values come from the seed YAML,
// docs/plan/counts.json (generated by tools/counts.mjs), lineage.json, the
// originals' SHA256SUMS and the original files, never from the defs.

import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { parse } from "yaml";
import { z } from "zod";
import { FEATURE_KINDS, isThrownCommandError, type ArchetypeDef } from "@hackbuild/spec";
import {
  ADDED_ARCHETYPES, ARCHETYPE_ALIASES, ARCHETYPE_DEFS, COMMAND_ALIASES, PACKAGE_ALIASES, PACKAGE_VERSION, SEED_FAMILY,
  archetypes, correctedLimits, loadArchetypes, refusedArchetype,
} from "@hackbuild/archetypes";
import { originalPath } from "../../../tools/test-support/originals-root.js";

const root = new URL("../../../", import.meta.url);
const read = (p: string): string => readFileSync(new URL(p, root), "utf8");
const ORIG = originalPath("");
const sha = (path: string): string => createHash("sha256").update(readFileSync(path)).digest("hex");

const kindMult = z.string().regex(new RegExp(`^(?:${FEATURE_KINDS.join("|")})(?: x(?:\\d+|N))?$`));
/** The seed row shape (seed/archetypes.seed.yaml); a key outside it refuses the row. */
const seedRow = z.object({
  id: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  family: z.enum(Object.keys(SEED_FAMILY) as [string, ...string[]]),
  senses: z.array(z.string()).optional(),
  emits: z.array(kindMult),
  params: z.record(z.string(), z.unknown()).optional(),
  stack: z.array(z.string()).optional(),
  materials: z.record(z.string(), z.string()).optional(),
  hookup: z.string().optional(),
  geometry: z.union([z.string(), z.array(z.union([z.string(), z.record(z.string(), z.string())]))]).optional(),
  solver: z.string().optional(),
  numbers: z.string().optional(),
  fits: z.array(z.string()).optional(),
  firmware: z.string().optional(),
  limits: z.array(z.string()).optional(),
  provenance: z.string().min(1),
}).strict();
type SeedRow = z.infer<typeof seedRow>;

const seed: SeedRow[] = (parse(read("packages/archetypes/seed/archetypes.seed.yaml")) as unknown[]).map((r) => seedRow.parse(r));
interface CanonCount { registered: number; byStatus: Record<string, number>; aliases?: number }
const counts = JSON.parse(read("docs/plan/counts.json")) as { mechanisms: number; archetypes: number; canon: Record<"mechanisms" | "archetypes", CanonCount> };
const defDir = new URL("packages/archetypes/src/defs/", root);
const defFiles = [
  ...readdirSync(defDir).filter((f) => f.endsWith(".ts") && f !== "index.ts").map((f) => f.slice(0, -3)),
  ...readdirSync(new URL("feeler/", defDir)).filter((f) => f.endsWith(".ts") && f !== "index.ts").map((f) => `feeler-${f.slice(0, -3)}`),
  // The originals canon additions (M06-T14).
  ...readdirSync(new URL("originals/", defDir)).filter((f) => f.endsWith(".ts") && f !== "index.ts").map((f) => f.slice(0, -3)),
].sort();

interface LineageRow { id: string; kind: "canonical" | "copy"; source: string; sha256: string }
const lineage = JSON.parse(read("lineage.json")) as LineageRow[];

/** The seed's emits with multiplicity expanded; xN is one entry, its count set by params. */
const expand = (emits: readonly string[]): string[] =>
  emits.flatMap((e) => {
    const [kind = e, n] = e.split(" x");
    return n === undefined || n === "N" ? [kind] : Array.from({ length: Number(n) }, () => kind);
  });

/** A copy of o without key k, so the key is absent rather than undefined. */
const without = <T extends object>(o: T, k: keyof T): Partial<T> => Object.fromEntries(Object.entries(o).filter(([key]) => key !== k)) as Partial<T>;

function thrown(fn: () => unknown): { code: string; path?: string; hint: string; didYouMean?: readonly string[] } {
  try { fn(); } catch (e) {
    if (isThrownCommandError(e)) return e.hbf;
    throw e;
  }
  throw new Error("no error thrown");
}

describe("archetype registry load", () => {
  test("every seeded id resolves, directly or through one alias; the seed size is the generated count", () => {
    expect(seed.length).toBe(counts.archetypes);
    let direct = 0;
    let aliased = 0;
    for (const row of seed) {
      const e = archetypes.get(row.id);
      expect(e, `seed id ${row.id} resolves to nothing`).toBeDefined();
      if (e?.id === row.id) direct++;
      else {
        aliased++;
        expect(archetypes.aliasOf(row.id)).toBe(e?.id);
        expect(defFiles).not.toContain(row.id);
      }
    }
    expect(aliased).toBe(ARCHETYPE_ALIASES.length);
    expect(direct + aliased).toBe(seed.length);
    console.log(`archetypes: ${seed.length} seeded ids resolve, ${direct} directly and ${aliased} through the alias table; ${archetypes.ids().length} registered`);
  });

  test("def files, the defs index and the registry agree; a def without a seed row is listed in added.ts", () => {
    const seedIds = new Set(seed.map((r) => r.id));
    const added = ADDED_ARCHETYPES.map((a) => a.id);
    expect(ARCHETYPE_DEFS.map((d) => d.id).sort()).toEqual(defFiles);
    expect([...archetypes.ids()]).toEqual(defFiles);
    for (const id of defFiles) expect(seedIds.has(id) || added.includes(id), `${id} is neither seeded nor in added.ts`).toBe(true);
    for (const a of ADDED_ARCHETYPES) {
      expect(seedIds.has(a.id), `${a.id} is seeded and listed as added`).toBe(false);
      expect(defFiles).toContain(a.id);
      if (a.splitFrom !== null) expect(seedIds.has(a.splitFrom), `${a.id} splits from ${a.splitFrom}, no seed row`).toBe(true);
    }
    // Every alias target is one of the entries split from that seed row.
    for (const al of ARCHETYPE_ALIASES) {
      expect(ADDED_ARCHETYPES.find((a) => a.id === al.to)?.splitFrom).toBe(al.alias);
    }
  });

  test("ids and aliases are unique; each alias resolves to exactly one registered id", () => {
    const ids = archetypes.ids();
    expect(new Set(ids).size).toBe(ids.length);
    const aliases = ARCHETYPE_ALIASES.map((a) => a.alias);
    expect(new Set(aliases).size).toBe(aliases.length);
    for (const a of ARCHETYPE_ALIASES) {
      expect(ids).not.toContain(a.alias);
      expect(archetypes.resolve(a.alias).id).toBe(a.to);
    }
  });

  test("the alias tables equal the M06-T01 step 4 table of the card", () => {
    const card = read("docs/plan/milestones/M06-canons.md");
    const t01 = card.slice(card.indexOf("## M06-T01 "), card.indexOf("## M06-T02 "));
    const rows = [...t01.matchAll(/^\s*\| (`[^|]+`)(?: \([^)]*\))? \| `([a-z.]+(?:-[a-z0-9]+)*)`(?:, `([a-z.]+)`)? \| (D-\d+)/gm)];
    const seedIds: Record<string, string> = {};
    const other: Record<string, string> = {};
    for (const [line, names, to, to2, decision] of rows) {
      const from = [...(names as string).matchAll(/`([^`]+)`/g)].map((m) => m[1] as string);
      const targets = to2 === undefined ? from.map(() => to as string) : [to as string, to2];
      from.forEach((f, i) => {
        if (line.includes("(seed id)")) seedIds[f] = targets[i] as string;
        else other[f] = targets[i] as string;
      });
      expect(decision).toMatch(/^D-0(14|96)$/);
    }
    expect(Object.keys(seedIds).length).toBeGreaterThan(0);
    expect(Object.fromEntries(ARCHETYPE_ALIASES.map((a) => [a.alias, a.to]))).toEqual(seedIds);
    expect({ ...PACKAGE_ALIASES, ...COMMAND_ALIASES }).toEqual(other);
    const names = new URL("registry/names.json", root);
    if (existsSync(names)) {
      const never = JSON.parse(readFileSync(names, "utf8")) as { neverSuggest?: string[] };
      for (const id of archetypes.ids()) expect(never.neverSuggest ?? []).not.toContain(id);
    }
  });

  test("each def carries its seed row's family (mapped), senses, emits, limits and provenance", () => {
    for (const row of seed) {
      const e = archetypes.resolve(row.id);
      const split = e.id !== row.id;
      const fam = SEED_FAMILY[row.family as keyof typeof SEED_FAMILY];
      expect([...e.def.senses], row.id).toEqual(row.senses ?? []);
      expect([...e.def.emits], row.id).toEqual(expand(row.emits));
      if (!split) {
        expect(e.def.family, row.id).toBe(fam);
        // The seed's limits with the D-096 corrections of M06-T07 applied (src/corrections.ts).
        expect([...e.def.limits], row.id).toEqual(correctedLimits(row.id, row.limits ?? []));
        expect(e.def.provenance, row.id).toBe(row.provenance);
      }
    }
    // A split entry keeps the seed's senses and emits; its provenance names one design of the seed row.
    for (const a of ADDED_ARCHETYPES) {
      if (a.splitFrom === null) continue;
      const row = seed.find((r) => r.id === a.splitFrom) as SeedRow;
      const d = archetypes.resolve(a.id).def;
      expect([...d.senses], a.id).toEqual(row.senses ?? []);
      expect([...d.emits], a.id).toEqual(expand(row.emits));
      expect(row.provenance, a.id).toContain(d.provenance.split(" ")[0] as string);
    }
  });

  test("every original is pinned: bytes, lineage.json and SHA256SUMS agree; the first is a canonical row", () => {
    // TANG r6_0 is the only file that holds the meander; lineage.json lists it as a copy of the r6-4 subject.
    // blocks-touch-brick ports from BOSS parts.js, a copy of the BLOCKS parts subject, because the BLOCKS rename broke it (M06-T14).
    const copyPrimary = new Set(["printed-pullup-meander", "blocks-touch-brick"]);
    for (const e of archetypes.entries) {
      const originals = e.def.original ?? [];
      if (originals.length === 0) {
        expect(e.def.status, `${e.id} names no original and is runnable`).not.toBe("proven");
        expect(e.def.statusReason).toContain("no original");
        continue;
      }
      originals.forEach((o, i) => {
        const path = `${ORIG}${o.slug}/${o.file}`;
        expect(existsSync(path), `${e.id} original ${path} is missing`).toBe(true);
        expect(sha(path), `${e.id} ${o.file} bytes`).toBe(o.sha256);
        const rows = lineage.filter((r) => r.source === path);
        expect(rows.length, `${e.id} ${path} has no lineage.json row`).toBeGreaterThan(0);
        for (const r of rows) expect(r.sha256, `lineage ${r.id}`).toBe(o.sha256);
        if (i === 0 && !copyPrimary.has(e.id)) expect(rows.some((r) => r.kind === "canonical"), `${e.id} ports from ${path}, which has no canonical row`).toBe(true);
        const sums = readFileSync(`${ORIG}${o.slug}/SHA256SUMS`, "utf8").split("\n").find((l) => l.endsWith(`  ${o.file}`));
        expect(sums, `${o.slug}/SHA256SUMS lists ${o.file}`).toBeDefined();
        expect(sums?.slice(0, 64)).toBe(o.sha256);
      });
    }
  });

  test("the generated registry counts in counts.json equal the loaded registry (D-010)", () => {
    const by: Record<string, number> = {};
    for (const e of archetypes.entries) by[e.def.status] = (by[e.def.status] ?? 0) + 1;
    expect(counts.canon.archetypes.registered).toBe(archetypes.ids().length);
    expect(counts.canon.archetypes.byStatus).toEqual(by);
    expect(counts.canon.archetypes.aliases).toBe(ARCHETYPE_ALIASES.length);
  });

  test("entries register under the archetypes kind with a manifest at the package version", () => {
    const pkg = JSON.parse(read("packages/archetypes/package.json")) as { name: string; version: string };
    expect(PACKAGE_VERSION).toBe(pkg.version);
    for (const e of archetypes.entries) {
      expect(e.kind).toBe("archetypes");
      expect(e.version).toBe(e.def.version);
      expect(e.manifest.name).toBe(pkg.name);
      expect(e.manifest.registry).toBe("archetypes");
      expect(e.manifest.provides).toEqual(archetypes.ids());
    }
  });
});

describe("refusals", () => {
  test("an unknown id is E_REF with didYouMean over ids and aliases", () => {
    const err = thrown(() => archetypes.resolve("printed-membrane-slidr"));
    expect(err.code).toBe("E_REF");
    expect(err.didYouMean).toContain("printed-membrane-slider");
  });

  test("a refused entry's derive() and apply() raise E_REF naming its status and reason", () => {
    for (const e of archetypes.entries) {
      if (e.def.status === "proven") continue;
      const err = thrown(() => e.def.derive({}, undefined as never));
      expect(err.code, e.id).toBe("E_REF");
      expect(err.hint, e.id).toBe(`archetype ${e.id} is ${e.def.status}: ${e.def.statusReason}`);
      expect(thrown(() => e.def.apply(undefined as never)).code).toBe("E_REF");
    }
  });

  const base = refusedArchetype({
    id: "probe-archetype", family: "printed", channels: 1, senses: [], emits: ["conductor"], read: "adc", limits: [],
    provenance: "probe", status: "candidate", statusReason: "probe", original: [],
  });
  const refused = (def: unknown): { code: string; path?: string } => thrown(() => loadArchetypes([def as ArchetypeDef], []));

  test("the loader refuses a def that does not type", () => {
    expect(loadArchetypes([base], []).ids()).toEqual(["probe-archetype"]);
    expect(refused({ ...base, family: "board-or-copper" })).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/family" });
    expect(refused({ ...base, emits: ["latch"] })).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/emits/0" });
    expect(refused({ ...base, read: "capacitive" })).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/read" });
    expect(refused({ ...base, tier: "guessed" })).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/tier" });
    expect(refused(without(base, "statusReason"))).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/statusReason" });
    expect(refused({ ...without(base, "statusReason"), status: "proven" })).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/reference" });
    expect(refused(without(base, "apply"))).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/apply" });
    expect(thrown(() => loadArchetypes([base, base], []))).toMatchObject({ code: "E_SCHEMA", path: "/archetypes/probe-archetype/id" });
  });

  test("the loader refuses an alias that shadows an id, repeats, or names no entry", () => {
    const al = { alias: "probe-old", to: "probe-archetype", decision: "D-096", why: "probe" };
    expect(loadArchetypes([base], [al]).resolve("probe-old").id).toBe("probe-archetype");
    expect(thrown(() => loadArchetypes([base], [{ ...al, alias: "probe-archetype" }])).code).toBe("E_SCHEMA");
    expect(thrown(() => loadArchetypes([base], [al, al])).code).toBe("E_SCHEMA");
    expect(thrown(() => loadArchetypes([base], [{ ...al, to: "probe-missing" }]))).toMatchObject({ code: "E_SCHEMA", path: "/aliases/probe-old/to" });
  });
});
